// eslint-disable-next-line @typescript-eslint/no-redeclare
export const Plan = {
  free: 'free',
  starter: 'starter',
  pro: 'pro',
  enterprise: 'enterprise',
} as const;

/**
 * Plan kind: time-based subscription or count-based entry pack.
 */
